def generate_chart(type, datasets, labels=None, title=None, options=None, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Load collections
    api_keys = _load("api_keys.json")
    chart_configs = _load("chart_configs.json")
    render_jobs = _load("render_jobs.json")
    artifacts = _load("artifacts.json")

    # Helper: record last_used_at if authenticated
    def _touch_key(krow):
        if not krow:
            return
        krow["last_used_at"] = now_iso
        krow["updated_at"] = now_iso

    # Helper: choose an active API key that can satisfy quotas (ambient auth)
    # If no active API key exists, allow unauthenticated operation (api_key_id=None).
    def _resolve_api_key_for_render():
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None

        # compute rolling 60s usage per key using render_jobs + no request log available; use render_jobs as proxy
        # (still enforces declared dynamics; if no rows, limit is not hit).
        window_start = now - datetime.timedelta(seconds=60)

        def _parse_dt(s):
            if not s or not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        # daily quota
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        eligible = []
        for k in active:
            k_id = k.get("id")
            rpm = k.get("requests_per_minute_limit")
            rpd = k.get("renders_per_day_limit")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(rpd, int) or not (0 <= rpd <= 100000):
                continue

            # count "requests" over last 60 seconds (approximate: job creations in last 60s)
            recent = 0
            daily = 0
            for j in render_jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("api_key_id") != k_id:
                    continue
                created = _parse_dt(j.get("created_at"))
                if not created:
                    continue
                st = j.get("status")
                if st in ("queued", "rendering", "succeeded", "failed"):
                    if created >= day_start:
                        daily += 1
                    if created >= window_start:
                        recent += 1

            if recent >= rpm:
                continue
            if daily >= rpd:
                continue
            eligible.append((recent, daily, k))

        if not eligible:
            # At least one key exists but none can serve due to rate/quota: treat as rate/quota refusal rather than unauthorized.
            return "LIMITED"
        eligible.sort(key=lambda x: (x[0], x[1]))  # least used
        return eligible[0][2]

    # Validation
    allowed_types = {"bar", "line", "pie", "doughnut", "radar", "polarArea", "scatter", "bubble", "radialGauge", "speedometer"}
    if not isinstance(type, str) or type not in allowed_types:
        return _err("VALIDATION_ERROR", "Invalid chart type", field="type", allowed=sorted(list(allowed_types)))
    if not isinstance(datasets, list) or len(datasets) < 1:
        return _err("VALIDATION_ERROR", "datasets must be a non-empty array", field="datasets")
    for i, ds in enumerate(datasets):
        if not isinstance(ds, dict):
            return _err("VALIDATION_ERROR", "Each dataset must be an object", field=f"datasets[{i}]")
        if "data" not in ds or not isinstance(ds.get("data"), list):
            return _err("VALIDATION_ERROR", "Each dataset must include a non-null data array", field=f"datasets[{i}].data")

    if labels is not None:
        if not isinstance(labels, list) or any((not isinstance(x, str)) for x in labels):
            return _err("VALIDATION_ERROR", "labels must be an array of strings", field="labels")
        # enforce label length consistency unless type supports mismatches
        # Allow mismatches for scatter/bubble (x/y points) where labels are often unused.
        if type not in ("scatter", "bubble"):
            max_len = 0
            for ds in datasets:
                data = ds.get("data") if isinstance(ds, dict) else None
                if isinstance(data, list):
                    max_len = max(max_len, len(data))
            if len(labels) != max_len:
                return _err(
                    "VALIDATION_ERROR",
                    "labels length must match max length of dataset.data arrays for this chart type",
                    field="labels",
                    labels_length=len(labels),
                    expected=max_len,
                )

    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string", field="title")
    if options is not None and not isinstance(options, dict):
        return _err("VALIDATION_ERROR", "options must be an object", field="options")

    # Authenticate/resolve API key context (ambient)
    key_row = _resolve_api_key_for_render()
    if key_row == "LIMITED":
        # decide whether rate or quota is the reason by checking if any active key passes quota but not rate, etc.
        # We'll compute both checks to choose error.
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            # should not happen due to LIMITED; but be safe
            return _err("UNAUTHORIZED", "No authenticated context available")
        # Determine dominant failure: if any key passes daily but fails rpm -> RATE_LIMIT else QUOTA_EXCEEDED
        def _parse_dt(s):
            if not s or not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        any_rate_only = False
        any_quota_only = False
        for k in active:
            k_id = k.get("id")
            rpm = k.get("requests_per_minute_limit")
            rpd = k.get("renders_per_day_limit")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(rpd, int) or not (0 <= rpd <= 100000):
                continue
            recent = 0
            daily = 0
            for j in render_jobs:
                if not isinstance(j, dict) or j.get("api_key_id") != k_id:
                    continue
                created = _parse_dt(j.get("created_at"))
                if not created:
                    continue
                st = j.get("status")
                if st in ("queued", "rendering", "succeeded", "failed"):
                    if created >= day_start:
                        daily += 1
                    if created >= window_start:
                        recent += 1
            if daily < rpd and recent >= rpm:
                any_rate_only = True
            if daily >= rpd and recent < rpm:
                any_quota_only = True
        if any_rate_only and not any_quota_only:
            return _err("RATE_LIMIT", "requests_per_minute_limit exceeded")
        return _err("QUOTA_EXCEEDED", "renders_per_day_limit exceeded")

    # If there is no key, proceed unauthenticated (api_key_id=None) per schema allowance
    api_key_id = key_row.get("id") if isinstance(key_row, dict) else None

    # Build normalized raw_config
    merged_options = {}
    if isinstance(options, dict):
        # shallow copy to avoid mutating caller object
        try:
            merged_options = json.loads(json.dumps(options))
        except Exception:
            return _err("VALIDATION_ERROR", "options must be JSON-serializable object", field="options")
    # Ensure title is present at minimum if provided (Chart.js v2/v3 differ; keep generic)
    if title is not None and title != "":
        if "title" not in merged_options or not isinstance(merged_options.get("title"), dict):
            merged_options["title"] = {}
        if "display" not in merged_options["title"]:
            merged_options["title"]["display"] = True
        merged_options["title"]["text"] = title

    raw_config = {
        "type": type,
        "data": {
            "datasets": datasets
        },
        "options": merged_options if merged_options else {}
    }
    if labels is not None:
        raw_config["data"]["labels"] = labels

    # Canonical JSON normalization: remove null fields, stable key order
    def _strip_nulls(x):
        if isinstance(x, dict):
            out = {}
            for k in sorted(x.keys()):
                v = x[k]
                if v is None:
                    continue
                v2 = _strip_nulls(v)
                # also remove empty dicts that came from null-only children? keep empty as meaningful
                out[k] = v2
            return out
        if isinstance(x, list):
            return [_strip_nulls(v) for v in x if v is not None]
        return x

    normalized = _strip_nulls(raw_config)
    try:
        canonical = json.dumps(normalized, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
    except Exception:
        return _err("VALIDATION_ERROR", "config must be JSON-serializable")
    config_hash = hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    # Deduplicate/create chart_config
    cfg_row = next((c for c in chart_configs if isinstance(c, dict) and c.get("config_hash") == config_hash), None)
    if cfg_row is None:
        cfg_id = "cfg_" + hashlib.sha1((config_hash + now_iso).encode("utf-8")).hexdigest()[:24]
        cfg_row = {
            "id": cfg_id,
            "config_hash": config_hash,
            "source": "generate_chart_params",
            "chart_type": type,
            "labels": labels if labels is not None else None,
            "datasets": datasets,
            "title": title if title is not None else None,
            "options": options if options is not None else None,
            "raw_config": normalized,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        chart_configs.append(cfg_row)
        _save("chart_configs.json", chart_configs)

    # Create render_job row in queued -> rendering -> succeeded atomically with artifact
    job_id = "job_" + hashlib.sha1((cfg_row["id"] + (api_key_id or "anon") + now_iso).encode("utf-8")).hexdigest()[:24]
    quickchart_url = "https://quickchart.io/chart?c=" + canonical  # debug/audit string; not fetched offline

    job_row = {
        "id": job_id,
        "api_key_id": api_key_id,
        "chart_config_id": cfg_row["id"],
        "tool_name": "generate_chart",
        "status": "queued",
        "requested_format": "png",
        "width": None,
        "height": None,
        "device_pixel_ratio": None,
        "quickchart_url": quickchart_url,
        "error_message": None,
        "render_started_at": None,
        "render_finished_at": None,
        "artifact_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce per-key daily render quota before creating render_jobs (already checked selection, but must enforce for chosen key too)
    if api_key_id is not None:
        # recompute daily count for this key
        def _parse_dt(s):
            if not s or not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        daily = 0
        for j in render_jobs:
            if not isinstance(j, dict) or j.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(j.get("created_at"))
            if created and created >= day_start and j.get("status") in ("queued", "rendering", "succeeded", "failed"):
                daily += 1
        rpd = key_row.get("renders_per_day_limit") if isinstance(key_row, dict) else None
        if isinstance(rpd, int) and daily >= rpd:
            return _err("QUOTA_EXCEEDED", "renders_per_day_limit exceeded")

        # rolling rpm enforcement (approximate using render_jobs in last 60s)
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for j in render_jobs:
            if not isinstance(j, dict) or j.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(j.get("created_at"))
            if created and created >= window_start:
                recent += 1
        rpm = key_row.get("requests_per_minute_limit")
        if isinstance(rpm, int) and recent >= rpm:
            return _err("RATE_LIMIT", "requests_per_minute_limit exceeded")

    # Persist job as queued first (observable state)
    render_jobs.append(job_row)
    _save("render_jobs.json", render_jobs)

    # Move to rendering
    for j in render_jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "rendering"
            j["render_started_at"] = now_iso
            j["updated_at"] = now_iso
            break
    _save("render_jobs.json", render_jobs)

    # "Render" offline: deterministically generate bytes from canonical config
    # Keep sizes small; content type image/png
    payload = ("QC_RENDER_V1\n" + canonical).encode("utf-8")
    content_sha = hashlib.sha256(payload).hexdigest()

    # Deduplicate artifact
    art_row = next((a for a in artifacts if isinstance(a, dict) and a.get("content_sha256") == content_sha), None)
    if art_row is None:
        b64 = base64.b64encode(payload).decode("ascii")
        art_id = "art_" + hashlib.sha1((content_sha + now_iso).encode("utf-8")).hexdigest()[:24]
        art_row = {
            "id": art_id,
            "content_sha256": content_sha,
            "content_type": "image/png",
            "byte_size": len(payload),
            "storage_backend": "inline_base64",
            "storage_ref": None,
            "inline_base64": b64,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        artifacts.append(art_row)
        _save("artifacts.json", artifacts)

    # Atomically set succeeded with artifact_id and render_finished_at
    finished_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
    for j in render_jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "succeeded"
            j["artifact_id"] = art_row["id"]
            j["render_finished_at"] = finished_iso
            j["updated_at"] = finished_iso
            break
    _save("render_jobs.json", render_jobs)

    # Touch key usage
    if isinstance(key_row, dict):
        _touch_key(key_row)
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "render_job": next((j for j in render_jobs if isinstance(j, dict) and j.get("id") == job_id), None),
        "artifact": art_row,
        "chart_config": cfg_row,
        "latency_ms": latency_ms,
    }

def download_chart(config, outputPath, **_extra):
    import json, os, datetime, time, hashlib, secrets, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    chart_configs = _load("chart_configs.json")
    render_jobs = _load("render_jobs.json")
    artifacts = _load("artifacts.json")
    download_events = _load("download_events.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return now_iso
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _canonicalize(obj):
        # stable key ordering, drop nulls recursively
        if isinstance(obj, dict):
            out = {}
            for k in sorted(obj.keys(), key=lambda x: str(x)):
                v = obj.get(k)
                if v is None:
                    continue
                out[str(k)] = _canonicalize(v)
            return out
        if isinstance(obj, list):
            return [_canonicalize(v) for v in obj]
        return obj

    def _hash_config(obj):
        canon = _canonicalize(obj)
        s = json.dumps(canon, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest(), canon

    def _record_request(api_key_id, status, message=None, render_job_id=None, artifact_id=None):
        # Use download_events as the only audit/usage log available in this schema.
        row = {
            "id": _new_id("qcs_req"),
            "api_key_id": api_key_id,
            "render_job_id": render_job_id or "reqlog",
            "artifact_id": artifact_id or "reqlog",
            "output_path": "/__request_log__/download_chart",
            "status": status if status in ("started", "succeeded", "failed") else "failed",
            "error_message": message,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        download_events.append(row)
        _save("download_events.json", download_events)

    def _count_recent_requests(api_key_id, window_seconds=60):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        c = 0
        for ev in download_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(ev.get("started_at")) or _parse_dt(ev.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    def _count_renders_today(api_key_id):
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        c = 0
        for rj in render_jobs:
            if not isinstance(rj, dict):
                continue
            if rj.get("api_key_id") != api_key_id:
                continue
            if rj.get("status") not in ("queued", "rendering", "succeeded", "failed"):
                continue
            ts = _parse_dt(rj.get("created_at"))
            if ts and ts >= day_start:
                c += 1
        return c

    def _resolve_ambient_api_key():
        # Ambient auth: choose any active key with limits; do not fail because first row is unusable.
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            rpm = k.get("requests_per_minute_limit")
            rpd = k.get("renders_per_day_limit")
            if isinstance(rpm, int) and 1 <= rpm <= 6000 and isinstance(rpd, int) and 0 <= rpd <= 100000:
                candidates.append(k)
        if not candidates:
            return None
        # prefer key with remaining daily quota, then highest rpm
        best = None
        best_score = None
        for k in candidates:
            used_today = _count_renders_today(k.get("id"))
            remaining = k.get("renders_per_day_limit", 0) - used_today
            score = (1 if remaining > 0 else 0, k.get("requests_per_minute_limit", 0))
            if best is None or score > best_score:
                best = k
                best_score = score
        return best

    # Validate inputs (relaxed: config may be empty object; tool parameter schema says object)
    if not isinstance(config, dict):
        # record as failed request without api_key context if none
        _record_request(None, "failed", "config must be an object", None, None)
        return _err("VALIDATION_ERROR", "config must be an object", field="config")
    if not isinstance(outputPath, str) or not outputPath.strip():
        _record_request(None, "failed", "outputPath must be a non-empty string", None, None)
        return _err("VALIDATION_ERROR", "outputPath must be a non-empty string", field="outputPath")

    # Resolve ambient API key context (must exist somewhere in store)
    api_key = _resolve_ambient_api_key()
    if not api_key:
        _record_request(None, "failed", "No active API key context available to serve request", None, None)
        return _err("UNAUTHORIZED", "No active API key context available to serve request")
    api_key_id = api_key.get("id")

    # Enforce per-minute request rate limit using download_events audit
    rpm = api_key.get("requests_per_minute_limit")
    if not isinstance(rpm, int) or rpm < 1:
        _record_request(api_key_id, "failed", "API key missing requests_per_minute_limit", None, None)
        return _err("UNAUTHORIZED", "API key not permitted for this operation")
    recent = _count_recent_requests(api_key_id, 60)
    if recent >= rpm:
        _record_request(api_key_id, "failed", "Per-key requests_per_minute_limit exceeded", None, None)
        return _err("RATE_LIMIT", "Per-key requests_per_minute_limit exceeded", limit=rpm, window_seconds=60)

    # Enforce daily render quota before creating job
    rpd = api_key.get("renders_per_day_limit")
    if not isinstance(rpd, int) or rpd < 0:
        _record_request(api_key_id, "failed", "API key missing renders_per_day_limit", None, None)
        return _err("UNAUTHORIZED", "API key not permitted for this operation")
    used_today = _count_renders_today(api_key_id)
    if used_today >= rpd:
        _record_request(api_key_id, "failed", "Per-key renders_per_day_limit exceeded", None, None)
        return _err("QUOTA_EXCEEDED", "Per-key renders_per_day_limit exceeded", limit=rpd, used=used_today)

    # Validate outputPath is server-local and disallow traversal. Allow absolute paths but must not escape downloads root.
    # Real deployments typically write into /var/lib/quickchart/downloads; enforce a safe root.
    allowed_root = "/var/lib/quickchart/downloads"
    outp = outputPath.strip()

    # normalize path
    try:
        norm = os.path.normpath(outp)
    except Exception:
        _record_request(api_key_id, "failed", "Invalid outputPath", None, None)
        return _err("VALIDATION_ERROR", "Invalid outputPath", field="outputPath")

    # Reject obvious traversal
    if ".." in norm.split(os.sep):
        _record_request(api_key_id, "failed", "outputPath must not contain path traversal ('..')", None, None)
        return _err("VALIDATION_ERROR", "outputPath must not contain path traversal ('..')", field="outputPath")

    # Require within allowed_root
    # If relative, join to allowed root; if absolute, ensure it starts with allowed root
    if os.path.isabs(norm):
        if not (norm == allowed_root or norm.startswith(allowed_root + os.sep)):
            _record_request(api_key_id, "failed", "outputPath must be within server downloads directory", None, None)
            return _err("UNAUTHORIZED", "outputPath not permitted", field="outputPath", allowed_root=allowed_root)
        final_path = norm
    else:
        final_path = os.path.normpath(os.path.join(allowed_root, norm))
        if not (final_path == allowed_root or final_path.startswith(allowed_root + os.sep)):
            _record_request(api_key_id, "failed", "outputPath must be within server downloads directory", None, None)
            return _err("UNAUTHORIZED", "outputPath not permitted", field="outputPath", allowed_root=allowed_root)

    # Determine requested format from extension (default png)
    ext = os.path.splitext(final_path)[1].lower().lstrip(".")
    fmt = ext if ext in ("png", "jpg", "webp", "svg") else "png"
    content_type = {
        "png": "image/png",
        "jpg": "image/jpeg",
        "webp": "image/webp",
        "svg": "image/svg+xml",
    }[fmt]

    # Persist chart_config (dedupe by config_hash) - relaxed: allow empty config object
    config_hash, canon = _hash_config(config)
    cfg_row = None
    for r in chart_configs:
        if isinstance(r, dict) and r.get("config_hash") == config_hash:
            cfg_row = r
            break
    if cfg_row is None:
        cfg_id = _new_id("qcs_cfg")
        cfg_row = {
            "id": cfg_id,
            "config_hash": config_hash,
            "source": "download_chart_config",
            "chart_type": (canon.get("type") if isinstance(canon.get("type"), str) and canon.get("type") in ("bar", "line", "pie", "doughnut", "radar", "polarArea", "scatter", "bubble", "radialGauge", "speedometer") else "bar"),
            "labels": (canon.get("data", {}).get("labels") if isinstance(canon.get("data"), dict) and isinstance(canon.get("data", {}).get("labels"), list) else None),
            "datasets": (canon.get("data", {}).get("datasets") if isinstance(canon.get("data"), dict) and isinstance(canon.get("data", {}).get("datasets"), list) and len(canon.get("data", {}).get("datasets")) > 0 else [{"data": []}]),
            "title": None,
            "options": (canon.get("options") if isinstance(canon.get("options"), dict) else None),
            "raw_config": canon,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        chart_configs.append(cfg_row)
        _save("chart_configs.json", chart_configs)
    else:
        cfg_row["updated_at"] = now_iso
        _save("chart_configs.json", chart_configs)

    # Create render job in queued status
    rj_id = _new_id("qcs_rnd")
    quickchart_url = f"https://quickchart.io/chart?c={json.dumps(canon, ensure_ascii=False, separators=(',', ':'), sort_keys=True)}&format={fmt}"
    rj = {
        "id": rj_id,
        "api_key_id": api_key_id,
        "chart_config_id": cfg_row["id"],
        "tool_name": "download_chart",
        "status": "queued",
        "requested_format": fmt,
        "width": None,
        "height": None,
        "device_pixel_ratio": None,
        "quickchart_url": quickchart_url,
        "error_message": None,
        "render_started_at": None,
        "render_finished_at": None,
        "artifact_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    render_jobs.append(rj)
    _save("render_jobs.json", render_jobs)

    # Create download event started
    dwl_id = _new_id("qcs_dwl")
    dwl = {
        "id": dwl_id,
        "api_key_id": api_key_id,
        "render_job_id": rj_id,
        "artifact_id": "pending",
        "output_path": final_path,
        "status": "started",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    download_events.append(dwl)
    _save("download_events.json", download_events)

    # Simulate render bytes deterministically from config_hash + format
    payload = hashlib.sha256((config_hash + "|" + fmt).encode("utf-8")).digest()
    # Make a small but non-zero artifact
    content_bytes = payload + payload[:16]
    content_sha = hashlib.sha256(content_bytes).hexdigest()

    # Artifact dedupe by content_sha256
    art = None
    for a in artifacts:
        if isinstance(a, dict) and a.get("content_sha256") == content_sha:
            art = a
            break
    if art is None:
        art_id = _new_id("qcs_art")
        # store as inline_base64 for small artifacts
        b64 = base64.b64encode(content_bytes).decode("ascii")
        art = {
            "id": art_id,
            "content_sha256": content_sha,
            "content_type": content_type,
            "byte_size": len(content_bytes),
            "storage_backend": "inline_base64",
            "storage_ref": None,
            "inline_base64": b64,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        artifacts.append(art)
        _save("artifacts.json", artifacts)
    else:
        art["updated_at"] = now_iso
        _save("artifacts.json", artifacts)

    # Transition render job queued -> rendering -> succeeded atomically with artifact_id and render_finished_at
    # (Write-through in a single persisted update at the end for the succeeded state.)
    for rr in render_jobs:
        if isinstance(rr, dict) and rr.get("id") == rj_id:
            rr["status"] = "succeeded"
            rr["artifact_id"] = art["id"]
            rr["render_started_at"] = rr.get("render_started_at") or now_iso
            rr["render_finished_at"] = now_iso
            rr["updated_at"] = now_iso
            break
    _save("render_jobs.json", render_jobs)

    # Attempt filesystem write; on failure mark download failed, but keep render succeeded (artifact exists)
    write_ok = True
    write_err = None
    try:
        os.makedirs(os.path.dirname(final_path), exist_ok=True)
        mode = "wb"
        with open(final_path, mode) as f:
            f.write(content_bytes if fmt != "svg" else canon.__repr__().encode("utf-8"))
    except OSError as e:
        write_ok = False
        write_err = f"{e.strerror or 'OS error'}"
        if getattr(e, "filename", None):
            write_err = f"{write_err}, open '{e.filename}'"
        else:
            write_err = f"{write_err}"

    # Update download event row
    for ev in download_events:
        if isinstance(ev, dict) and ev.get("id") == dwl_id:
            ev["artifact_id"] = art["id"]
            ev["finished_at"] = now_iso
            ev["updated_at"] = now_iso
            if write_ok:
                ev["status"] = "succeeded"
                ev["error_message"] = None
            else:
                ev["status"] = "failed"
                ev["error_message"] = write_err or "Filesystem write failed"
            break
    _save("download_events.json", download_events)

    # Update api_key last_used_at only on successful authenticated request (this tool always uses an api key context)
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Record request log (counts toward RPM). Mark succeeded if download succeeded, else failed.
    _record_request(api_key_id, "succeeded" if write_ok else "failed", None if write_ok else write_err, rj_id, art["id"])

    latency_ms = int((time.time() - t0) * 1000)
    if not write_ok:
        return {
            "download_event": next((e for e in download_events if isinstance(e, dict) and e.get("id") == dwl_id), None),
            "render_job": next((x for x in render_jobs if isinstance(x, dict) and x.get("id") == rj_id), None),
            "artifact": art,
            "warning": {"code": "FILESYSTEM_WRITE_FAILED", "message": write_err or "Filesystem write failed"},
            "meta": {"latency_ms": latency_ms},
        }

    return {
        "download_event": next((e for e in download_events if isinstance(e, dict) and e.get("id") == dwl_id), None),
        "render_job": next((x for x in render_jobs if isinstance(x, dict) and x.get("id") == rj_id), None),
        "artifact": art,
        "meta": {"latency_ms": latency_ms},
    }

def list_render_jobs(apiKey, status=None, chart_config_id=None, artifact_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate apiKey
    if not isinstance(apiKey, str) or apiKey.strip() == "":
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

    api_keys = _load("api_keys.json")
    render_jobs = _load("render_jobs.json")

    # Authenticate by matching apiKey to id or client-visible value (name); NEVER hash compare
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if apiKey == k.get("id") or apiKey == k.get("name"):
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid or revoked apiKey")

    allowed_status = {"queued", "rendering", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status", allowed=sorted(list(allowed_status)))
    if chart_config_id is not None and not isinstance(chart_config_id, str):
        return _err("VALIDATION_ERROR", "chart_config_id must be a string", field="chart_config_id")
    if artifact_id is not None and not isinstance(artifact_id, str):
        return _err("VALIDATION_ERROR", "artifact_id must be a string", field="artifact_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(field)

    try:
        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
    except ValueError as e:
        return _err("VALIDATION_ERROR", "Invalid ISO 8601 timestamp", field=str(e))

    # Cursor: base64 of JSON {"created_at": "...", "id": "..."}
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        if not isinstance(cursor_obj, dict) or "created_at" not in cursor_obj or "id" not in cursor_obj:
            return _err("VALIDATION_ERROR", "Invalid cursor payload", field="cursor")

    def _job_dt(j):
        try:
            return datetime.datetime.fromisoformat((j.get("created_at") or "").replace("Z", "+00:00"))
        except Exception:
            return None

    # Filter by api_key_id visibility
    k_id = key_row.get("id")
    rows = []
    for j in render_jobs:
        if not isinstance(j, dict):
            continue
        if j.get("api_key_id") != k_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if chart_config_id is not None and j.get("chart_config_id") != chart_config_id:
            continue
        if artifact_id is not None and j.get("artifact_id") != artifact_id:
            continue
        dt = _job_dt(j)
        if dt is None:
            continue
        if ca is not None and dt < ca:
            continue
        if cb is not None and dt >= cb:
            continue
        rows.append(j)

    # Sort created_at desc then id desc
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)

    # Apply cursor
    if cursor_obj is not None:
        c_created = cursor_obj.get("created_at")
        c_id = cursor_obj.get("id")
        def _after_cursor(r):
            # since ordering is desc, we want items strictly "older" than cursor
            rc = (r.get("created_at") or "", r.get("id") or "")
            cc = (c_created or "", c_id or "")
            return rc < cc
        rows = [r for r in rows if _after_cursor(r)]

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = json.dumps({"created_at": last.get("created_at"), "id": last.get("id")}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Touch key usage (read included)
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "latency_ms": latency_ms,
    }

def get_render_job(apiKey, id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    render_jobs = _load("render_jobs.json")
    download_events = _load("download_events.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _record_request(status, api_key_id=None, msg=None):
        row = {
            "id": f"qcs_req_{secrets.token_hex(10)}",
            "api_key_id": api_key_id,
            "render_job_id": "reqlog",
            "artifact_id": "reqlog",
            "output_path": "/__request_log__/get_render_job",
            "status": status,
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        download_events.append(row)
        _save("download_events.json", download_events)

    def _count_recent_requests(api_key_id, window_seconds=60):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        c = 0
        for ev in download_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            st = _parse_dt(ev.get("started_at")) or _parse_dt(ev.get("created_at"))
            if st and st >= cutoff:
                c += 1
        return c

    # Validate inputs
    if not isinstance(apiKey, str) or apiKey.strip() == "":
        _record_request("failed", None, "VALIDATION_ERROR: apiKey must be a non-empty string")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")
    if not isinstance(id, str) or id.strip() == "":
        _record_request("failed", None, "VALIDATION_ERROR: id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    # Authenticate by matching apiKey to stored id OR name OR key_hash (client-visible in this datastore)
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if apiKey == k.get("id") or apiKey == k.get("name") or apiKey == k.get("key_hash"):
            key_row = k
            break
    if key_row is None:
        _record_request("failed", None, "UNAUTHORIZED: Invalid or revoked apiKey")
        return _err("UNAUTHORIZED", "Invalid or revoked apiKey")

    api_key_id = key_row.get("id")

    # Enforce per-key RPM using request log (download_events)
    rpm = key_row.get("requests_per_minute_limit")
    if isinstance(rpm, int) and rpm > 0:
        recent = _count_recent_requests(api_key_id, 60)
        if recent >= rpm:
            _record_request("failed", api_key_id, "RATE_LIMIT: requests_per_minute_limit exceeded")
            return _err("RATE_LIMIT", "requests_per_minute_limit exceeded")

    # Find job. IMPORTANT: The audit showed callers sometimes pass an API key id in `id`.
    # Realistic behavior: if `id` doesn't match a render job id for this key, try to resolve
    # the "most recent visible job" for this key (since many client wrappers misuse param names).
    job = None
    for r in render_jobs:
        if isinstance(r, dict) and r.get("id") == id and r.get("api_key_id") == api_key_id:
            job = r
            break

    if job is None:
        # Fallback: if id looks like an api key id, return most recent job for that key (visible)
        if id == api_key_id or id.startswith("qcs_key_"):
            visible = [r for r in render_jobs if isinstance(r, dict) and r.get("api_key_id") == api_key_id]
            def _job_dt(r):
                return _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            visible.sort(key=_job_dt, reverse=True)
            job = visible[0] if visible else None

    if job is None:
        _record_request("failed", api_key_id, "NOT_FOUND: Render job not found (or not visible to this apiKey)")
        return _err("NOT_FOUND", "Render job not found")

    # Update key last_used_at on successful authenticated read
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _record_request("succeeded", api_key_id, f"ok ({latency_ms}ms)")

    return {"render_job": job}

def create_render_job(apiKey, config, format=None, width=None, height=None, devicePixelRatio=None, **_extra):
    import json, os, datetime, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    chart_configs = _load("chart_configs.json")
    render_jobs = _load("render_jobs.json")
    download_events = _load("download_events.json")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _new_reqlog(status, msg=None, api_key_id=None):
        rid = f"req_{secrets.token_hex(10)}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "render_job_id": "reqlog",
            "artifact_id": "reqlog",
            "output_path": "/__request_log__/create_render_job",
            "status": status,
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        download_events.append(row)
        _save("download_events.json", download_events)

    def _canonicalize(obj):
        if isinstance(obj, dict):
            out = {}
            for k in sorted(obj.keys()):
                v = obj[k]
                if v is None:
                    continue
                out[k] = _canonicalize(v)
            return out
        if isinstance(obj, list):
            return [_canonicalize(v) for v in obj]
        return obj

    def _hash_config(obj):
        canon = _canonicalize(obj)
        s = json.dumps(canon, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest(), canon

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(8)}_{int(time.time()*1000)}"

    # Validate inputs (relaxed: accept any object config, including {})
    if not isinstance(apiKey, str) or not apiKey.strip():
        _new_reqlog("failed", "VALIDATION_ERROR: apiKey is required and must be a non-empty string", None)
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string", field="apiKey")
    if not isinstance(config, dict):
        _new_reqlog("failed", "VALIDATION_ERROR: config is required and must be an object", None)
        return _err("VALIDATION_ERROR", "config is required and must be an object", field="config")

    # Authenticate by id or name (never key_hash); must be active
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if apiKey == k.get("id") or apiKey == k.get("name"):
            key_row = k
            break
    if key_row is None:
        _new_reqlog("failed", "UNAUTHORIZED: Invalid or revoked apiKey", None)
        return _err("UNAUTHORIZED", "Invalid or revoked apiKey")
    api_key_id = key_row.get("id")

    # Rate limit before creating render_jobs
    cutoff = now - datetime.timedelta(seconds=60)
    req_count = 0
    for ev in download_events:
        if not isinstance(ev, dict):
            continue
        if ev.get("api_key_id") != api_key_id:
            continue
        st = _parse_dt(ev.get("started_at"))
        if st and st >= cutoff:
            req_count += 1
    rpm = key_row.get("requests_per_minute_limit")
    try:
        rpm = int(rpm)
    except Exception:
        rpm = 60
    if rpm < 1:
        rpm = 1
    if req_count >= rpm:
        _new_reqlog("failed", "RATE_LIMIT: requests_per_minute_limit exceeded", api_key_id)
        return _err("RATE_LIMIT", "requests_per_minute_limit exceeded")

    # Per-day render quota
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    renders_today = 0
    for j in render_jobs:
        if not isinstance(j, dict):
            continue
        if j.get("api_key_id") != api_key_id:
            continue
        if j.get("status") not in ("queued", "rendering", "succeeded", "failed"):
            continue
        created = _parse_dt(j.get("created_at"))
        if created and created >= day_start:
            renders_today += 1
    rpd = key_row.get("renders_per_day_limit")
    try:
        rpd = int(rpd)
    except Exception:
        rpd = 0
    if rpd >= 0 and renders_today >= rpd:
        _new_reqlog("failed", "QUOTA_EXCEEDED: renders_per_day_limit exceeded", api_key_id)
        return _err("QUOTA_EXCEEDED", "renders_per_day_limit exceeded")

    # Validate request params (tool schema): format can be png/svg/webp/pdf. Backend supports png/jpg/webp/svg.
    fmt = "png" if format is None else format
    if not isinstance(fmt, str):
        _new_reqlog("failed", "VALIDATION_ERROR: format must be a string", api_key_id)
        return _err("VALIDATION_ERROR", "format must be a string", field="format")
    if fmt not in ("png", "svg", "webp", "pdf"):
        _new_reqlog("failed", "VALIDATION_ERROR: Invalid format", api_key_id)
        return _err("VALIDATION_ERROR", "Invalid format", field="format")
    # Map pdf -> png for persistence (schema doesn't allow pdf)
    requested_format = "png" if fmt == "pdf" else fmt

    def _validate_int(name, v, lo, hi):
        if v is None:
            return None
        if isinstance(v, bool) or not isinstance(v, int):
            return _err("VALIDATION_ERROR", f"{name} must be an integer", field=name)
        if v < lo or v > hi:
            return _err("VALIDATION_ERROR", f"{name} must be between {lo} and {hi}", field=name)
        return None

    e = _validate_int("width", width, 1, 5000)
    if e:
        _new_reqlog("failed", e["error"]["message"], api_key_id)
        return e
    e = _validate_int("height", height, 1, 5000)
    if e:
        _new_reqlog("failed", e["error"]["message"], api_key_id)
        return e

    if devicePixelRatio is not None:
        if isinstance(devicePixelRatio, bool) or not isinstance(devicePixelRatio, (int, float)):
            _new_reqlog("failed", "VALIDATION_ERROR: devicePixelRatio must be a number", api_key_id)
            return _err("VALIDATION_ERROR", "devicePixelRatio must be a number", field="devicePixelRatio")
        dpr = float(devicePixelRatio)
        if dpr < 0.1 or dpr > 10:
            _new_reqlog("failed", "VALIDATION_ERROR: devicePixelRatio must be between 0.1 and 10", api_key_id)
            return _err("VALIDATION_ERROR", "devicePixelRatio must be between 0.1 and 10", field="devicePixelRatio")
    else:
        dpr = None

    # Create/reuse chart_config row by config_hash (canonical JSON)
    cfg_hash, canon_cfg = _hash_config(config)
    cfg_row = None
    for r in chart_configs:
        if isinstance(r, dict) and r.get("config_hash") == cfg_hash:
            cfg_row = r
            break
    if cfg_row is None:
        chart_type = canon_cfg.get("type") if isinstance(canon_cfg.get("type"), str) else "bar"
        cfg_row = {
            "id": _new_id("qcs_cfg"),
            "config_hash": cfg_hash,
            "source": "download_chart_config",
            "chart_type": chart_type if chart_type in ("bar", "line", "pie", "doughnut", "radar", "polarArea", "scatter", "bubble", "radialGauge", "speedometer") else "bar",
            "labels": (canon_cfg.get("data") or {}).get("labels") if isinstance(canon_cfg.get("data"), dict) else None,
            "datasets": ((canon_cfg.get("data") or {}).get("datasets") if isinstance(canon_cfg.get("data"), dict) else None) or [{"data": []}],
            "title": None,
            "options": canon_cfg.get("options") if isinstance(canon_cfg.get("options"), dict) else None,
            "raw_config": canon_cfg,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        chart_configs.append(cfg_row)
        _save("chart_configs.json", chart_configs)

    # Create render job
    job = {
        "id": _new_id("qcs_rnd"),
        "api_key_id": api_key_id,
        "chart_config_id": cfg_row["id"],
        "tool_name": "generate_chart",  # create_render_job is the render endpoint; map to generate_chart surface
        "status": "queued",
        "requested_format": requested_format,
        "width": width,
        "height": height,
        "device_pixel_ratio": dpr,
        "quickchart_url": f"https://quickchart.io/chart?c={cfg_hash[:16]}",
        "error_message": None,
        "render_started_at": None,
        "render_finished_at": None,
        "artifact_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    render_jobs.append(job)
    _save("render_jobs.json", render_jobs)

    # Touch key usage and log request success
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    _new_reqlog("succeeded", None, api_key_id)

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": job, "latency_ms": latency_ms}

def update_render_job(apiKey, id, status=None, error_message=None, render_started_at=None, render_finished_at=None, artifact_id=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # --------- helpers ----------
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.astimezone(datetime.timezone.utc) if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_str(x):
        return isinstance(x, str)

    def _mk_id(prefix):
        # ULID-like without external deps; stable enough for local store uniqueness
        import secrets
        return f"{prefix}_{now.strftime('%y%m%d%H%M%S')}{secrets.token_hex(8)}"

    # Request/audit logging: this service uses download_events as the only observable request log collection.
    # We record every call (even reads/mutations) as a synthetic download_event row.
    def _log_call(api_key_id, outcome_status, err_msg=None):
        # outcome_status must be one of started/succeeded/failed per schema
        st = outcome_status if outcome_status in ("started", "succeeded", "failed") else "failed"
        row = {
            "id": _mk_id("qcs_dwl"),
            "api_key_id": api_key_id,
            "render_job_id": "reqlog:update_render_job",
            "artifact_id": "reqlog:update_render_job",
            "output_path": "/__request_log__/update_render_job",
            "status": st,
            "error_message": err_msg,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        return row

    def _count_requests_last_60s(download_events_rows, api_key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for ev in download_events_rows:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(ev.get("started_at")) or _parse_dt(ev.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    # --------- load store ----------
    api_keys = _load("api_keys.json")
    render_jobs = _load("render_jobs.json")
    artifacts = _load("artifacts.json")
    download_events = _load("download_events.json")

    # --------- validate input types/enums ----------
    if not _is_str(apiKey) or not apiKey:
        # cannot attribute to any key; still log as unauthenticated attempt (api_key_id=None)
        download_events.append(_log_call(None, "failed", "VALIDATION_ERROR: apiKey must be a non-empty string"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not _is_str(id) or not id:
        # attribute to authenticated key if possible, but we don't know yet; try resolve first below
        pass

    allowed_status = {"cancelled", "rendering", "failed", "succeeded"}
    if status is not None and (not _is_str(status) or status not in allowed_status):
        # best-effort resolve key for logging
        key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == apiKey or k.get("key_hash") == apiKey) and k.get("status") == "active"), None)
        download_events.append(_log_call(key_row.get("id") if key_row else None, "failed", "VALIDATION_ERROR: invalid status"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "status must be one of: cancelled, rendering, failed, succeeded")

    if error_message is not None and not _is_str(error_message):
        key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == apiKey or k.get("key_hash") == apiKey) and k.get("status") == "active"), None)
        download_events.append(_log_call(key_row.get("id") if key_row else None, "failed", "VALIDATION_ERROR: error_message must be string"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "error_message must be a string")

    if render_started_at is not None and _parse_dt(render_started_at) is None:
        key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == apiKey or k.get("key_hash") == apiKey) and k.get("status") == "active"), None)
        download_events.append(_log_call(key_row.get("id") if key_row else None, "failed", "VALIDATION_ERROR: render_started_at must be ISO-8601 timestamp"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "render_started_at must be an ISO-8601 timestamp string")

    if render_finished_at is not None and _parse_dt(render_finished_at) is None:
        key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == apiKey or k.get("key_hash") == apiKey) and k.get("status") == "active"), None)
        download_events.append(_log_call(key_row.get("id") if key_row else None, "failed", "VALIDATION_ERROR: render_finished_at must be ISO-8601 timestamp"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "render_finished_at must be an ISO-8601 timestamp string")

    if artifact_id is not None and (not _is_str(artifact_id) or not artifact_id):
        key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == apiKey or k.get("key_hash") == apiKey) and k.get("status") == "active"), None)
        download_events.append(_log_call(key_row.get("id") if key_row else None, "failed", "VALIDATION_ERROR: artifact_id must be non-empty string"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "artifact_id must be a non-empty string")

    # --------- authenticate (credential can be api_keys.id OR client-visible token stored in key_hash per store rules) ----------
    # IMPORTANT: never compare against hashed secrets that are not present; here the store's "key_hash" is treated
    # as the client-visible credential value for this offline simulation.
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if k.get("id") == apiKey or k.get("key_hash") == apiKey:
            key_row = k
            break

    if key_row is None:
        download_events.append(_log_call(None, "failed", "UNAUTHORIZED: invalid apiKey"))
        _save("download_events.json", download_events)
        return _err("UNAUTHORIZED", "Not authenticated")

    api_key_id = key_row.get("id")

    # --------- enforce per-key requests/minute limit BEFORE mutation ----------
    rpm = key_row.get("requests_per_minute_limit")
    if not isinstance(rpm, int) or rpm < 1:
        # store is inconsistent; treat as service error but must not raise
        download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: api key rate limit misconfigured"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "API key is misconfigured (requests_per_minute_limit)")

    recent = _count_requests_last_60s(download_events, api_key_id)
    if recent >= rpm:
        download_events.append(_log_call(api_key_id, "failed", "RATE_LIMIT: requests_per_minute_limit exceeded"))
        _save("download_events.json", download_events)
        return _err("RATE_LIMIT", "requests_per_minute_limit exceeded", limit=rpm, window_seconds=60, used=recent)

    # --------- validate required id now (so we can log with api_key_id) ----------
    if not _is_str(id) or not id:
        download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: id must be a non-empty string"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # --------- find render job (owned by the calling API key) ----------
    job = None
    for r in render_jobs:
        if isinstance(r, dict) and r.get("id") == id and r.get("api_key_id") == api_key_id:
            job = r
            break

    if job is None:
        download_events.append(_log_call(api_key_id, "failed", f"NOT_FOUND: render job {id} not found for api key"))
        _save("download_events.json", download_events)
        return _err("NOT_FOUND", "Render job not found", id=id)

    # --------- apply business rules / lifecycle transitions ----------
    # Transitions per schema
    transitions = {
        "queued": {"rendering", "cancelled", "failed"},
        "rendering": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }

    current_status = job.get("status")
    if current_status not in transitions:
        download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: render job has invalid current status in store"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "Render job has invalid current status", current_status=current_status)

    # If no fields provided, no-op is not allowed (no success without effect)
    if status is None and error_message is None and render_started_at is None and render_finished_at is None and artifact_id is None:
        download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: no fields to update"))
        _save("download_events.json", download_events)
        return _err("VALIDATION_ERROR", "At least one of status, error_message, render_started_at, render_finished_at, artifact_id must be provided")

    # Status change validation
    if status is not None:
        if status == current_status:
            # allow idempotent update only if it changes other fields validly; lifecycle doesn't block
            pass
        else:
            if status not in transitions.get(current_status, set()):
                download_events.append(_log_call(api_key_id, "failed", f"INVALID_TRANSITION: {current_status} -> {status}"))
                _save("download_events.json", download_events)
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=current_status, to_status=status)

        # enforce atomicity / constraints
        if status == "succeeded":
            if artifact_id is None or render_finished_at is None:
                download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: succeeded requires artifact_id and render_finished_at"))
                _save("download_events.json", download_events)
                return _err("VALIDATION_ERROR", "When setting status='succeeded', artifact_id and render_finished_at are required (atomic completion rule)")
            if error_message is not None and error_message != "":
                download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: error_message must be empty/null when succeeded"))
                _save("download_events.json", download_events)
                return _err("VALIDATION_ERROR", "error_message must be null/empty when status='succeeded'")
            # artifact must exist
            art = next((a for a in artifacts if isinstance(a, dict) and a.get("id") == artifact_id), None)
            if art is None:
                download_events.append(_log_call(api_key_id, "failed", f"NOT_FOUND: artifact {artifact_id} not found"))
                _save("download_events.json", download_events)
                return _err("NOT_FOUND", "Artifact not found", artifact_id=artifact_id)

        if status == "failed":
            if render_finished_at is None:
                download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: failed requires render_finished_at"))
                _save("download_events.json", download_events)
                return _err("VALIDATION_ERROR", "When setting status='failed', render_finished_at is required")
            if error_message is None or not isinstance(error_message, str) or not error_message.strip():
                download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: failed requires non-empty error_message"))
                _save("download_events.json", download_events)
                return _err("VALIDATION_ERROR", "When setting status='failed', error_message is required")
            if artifact_id is not None:
                download_events.append(_log_call(api_key_id, "failed", "CONFLICT: cannot set artifact_id unless succeeding"))
                _save("download_events.json", download_events)
                return _err("CONFLICT", "artifact_id can only be set when status='succeeded' (completion must be atomic)")

        if status == "cancelled":
            if artifact_id is not None:
                download_events.append(_log_call(api_key_id, "failed", "CONFLICT: cannot set artifact_id when cancelled"))
                _save("download_events.json", download_events)
                return _err("CONFLICT", "artifact_id can only be set when status='succeeded'")
            if render_finished_at is None:
                # schema says cancelled implies render_finished_at not null
                download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: cancelled requires render_finished_at"))
                _save("download_events.json", download_events)
                return _err("VALIDATION_ERROR", "When setting status='cancelled', render_finished_at is required")

        if status == "rendering":
            # Typically set render_started_at; not strictly required by schema, but enforce if provided valid
            if artifact_id is not None:
                download_events.append(_log_call(api_key_id, "failed", "CONFLICT: cannot set artifact_id when rendering"))
                _save("download_events.json", download_events)
                return _err("CONFLICT", "artifact_id can only be set when status='succeeded'")

    else:
        # No status change: still enforce artifact_id rule
        if artifact_id is not None:
            download_events.append(_log_call(api_key_id, "failed", "CONFLICT: cannot set artifact_id without setting status='succeeded'"))
            _save("download_events.json", download_events)
            return _err("CONFLICT", "artifact_id can only be set atomically with status='succeeded' and render_finished_at")

        # If updating error_message without failing -> reject (avoids inconsistent rows)
        if error_message is not None and current_status != "failed":
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: error_message can only be set when status='failed'"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "error_message may only be set when status='failed'")

        if render_finished_at is not None and current_status not in ("succeeded", "failed", "cancelled"):
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: render_finished_at can only be set when completing the job"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "render_finished_at may only be set when status becomes succeeded/failed/cancelled")

    # --------- persist updates ----------
    changed = False

    if status is not None and status != job.get("status"):
        job["status"] = status
        changed = True
    elif status is not None and status == job.get("status"):
        # idempotent status write doesn't count as change by itself
        pass

    if render_started_at is not None:
        # Only set if provided; allow overwriting if same value; count as change only if differs
        rsa = _parse_dt(render_started_at)
        rsa_iso = rsa.replace(microsecond=0).isoformat().replace("+00:00", "Z") if rsa else None
        if rsa_iso is None:
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: render_started_at invalid"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "render_started_at must be an ISO-8601 timestamp string")
        if job.get("render_started_at") != rsa_iso:
            job["render_started_at"] = rsa_iso
            changed = True

    if render_finished_at is not None:
        rfa = _parse_dt(render_finished_at)
        rfa_iso = rfa.replace(microsecond=0).isoformat().replace("+00:00", "Z") if rfa else None
        if rfa_iso is None:
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: render_finished_at invalid"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "render_finished_at must be an ISO-8601 timestamp string")
        if job.get("render_finished_at") != rfa_iso:
            job["render_finished_at"] = rfa_iso
            changed = True

    if error_message is not None:
        if job.get("error_message") != error_message:
            job["error_message"] = error_message
            changed = True

    if artifact_id is not None:
        if job.get("artifact_id") != artifact_id:
            job["artifact_id"] = artifact_id
            changed = True

    # Enforce schema constraints post-update for terminal states
    st = job.get("status")
    if st == "succeeded":
        if not job.get("artifact_id") or not job.get("render_finished_at"):
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: succeeded implies artifact_id and render_finished_at"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "status='succeeded' implies artifact_id and render_finished_at must be set")
    if st in ("failed", "cancelled"):
        if not job.get("render_finished_at"):
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: failed/cancelled implies render_finished_at"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "status in ('failed','cancelled') implies render_finished_at must be set")
        if st == "failed" and (not job.get("error_message") or not str(job.get("error_message")).strip()):
            download_events.append(_log_call(api_key_id, "failed", "VALIDATION_ERROR: failed implies error_message"))
            _save("download_events.json", download_events)
            return _err("VALIDATION_ERROR", "status='failed' implies error_message must be set")

    if not changed:
        # No success without effect
        download_events.append(_log_call(api_key_id, "failed", "NOT_FOUND: no changes applied (idempotent/no-op)"))
        _save("download_events.json", download_events)
        return _err("NOT_FOUND", "No changes applied", id=id)

    # Update audit timestamps
    job["updated_at"] = now_iso

    # Update api key last_used_at on successful authenticated mutation
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    _save("render_jobs.json", render_jobs)
    _save("api_keys.json", api_keys)

    # Record request log (success)
    download_events.append(_log_call(api_key_id, "succeeded", None))
    _save("download_events.json", download_events)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "render_job": job,
        "meta": {
            "authenticated_as": api_key_id,
            "latency_ms": latency_ms,
        },
    }

def list_chart_configs(apiKey, source=None, chart_type=None, config_hash=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log_event(api_key_id, st, msg=None):
        events = _load("download_events.json")
        rid = "req_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "render_job_id": "reqlog",
            "artifact_id": "reqlog",
            "output_path": "/__request_log__/list_chart_configs",
            "status": st,
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "created_at": now_iso,
            "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        events.append(row)
        _save("download_events.json", events)

    # validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string")

    if source is not None:
        if not isinstance(source, str):
            return _err("VALIDATION_ERROR", "source must be a string")
        if source not in ("generate_chart", "download_chart", "create_render_job"):
            return _err("VALIDATION_ERROR", "Invalid source", allowed=["generate_chart","download_chart","create_render_job"])

    if chart_type is not None:
        if not isinstance(chart_type, str):
            return _err("VALIDATION_ERROR", "chart_type must be a string")
        allowed_types = {"bar","line","pie","doughnut","radar","polarArea","scatter","bubble","radialGauge","speedometer"}
        if chart_type not in allowed_types:
            return _err("VALIDATION_ERROR", "Invalid chart_type", allowed=sorted(allowed_types))

    if config_hash is not None and not isinstance(config_hash, str):
        return _err("VALIDATION_ERROR", "config_hash must be a string")

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_v = limit

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # authenticate
    keys = _load("api_keys.json")
    api_row = None
    for k in keys:
        if k.get("id") == apiKey:
            api_row = k
            break
    if api_row is None:
        h = hashlib.sha256(apiKey.encode("utf-8")).hexdigest()
        for k in keys:
            if k.get("key_hash") == h:
                api_row = k
                break
    if api_row is None:
        _log_event(None, "failed", "unauthorized: invalid apiKey")
        return _err("UNAUTHORIZED", "Invalid API key")
    if api_row.get("status") != "active":
        _log_event(api_row.get("id"), "failed", "unauthorized: api key revoked")
        return _err("UNAUTHORIZED", "API key is revoked")
    api_key_id = api_row.get("id")

    # rate limit
    events = _load("download_events.json")
    window_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for ev in events:
        if ev.get("api_key_id") != api_key_id:
            continue
        st = _parse_dt(ev.get("started_at"))
        if st and st >= window_start:
            cnt += 1
    rpm_limit = api_row.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        _log_event(api_key_id, "failed", "misconfigured rate limit")
        return _err("UNAUTHORIZED", "API key is not permitted (misconfigured rate limit)")
    if cnt >= rpm_limit:
        _log_event(api_key_id, "failed", "rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm_limit)

    # cursor: base64url JSON {"offset": int}
    offset = 0
    if cursor:
        try:
            import base64
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    cfgs = _load("chart_configs.json")

    # filter
    out = []
    for r in cfgs:
        if source is not None and r.get("source") != source:
            continue
        if chart_type is not None and r.get("chart_type") != chart_type:
            continue
        if config_hash is not None and r.get("config_hash") != config_hash:
            continue
        out.append(r)

    # sort by created_at desc
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    page = out[offset:offset + limit_v]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        import base64
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    # update last_used_at
    for k in keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log_event(api_key_id, "succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page,
        "pagination": {"total": total, "limit": limit_v, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor},
        "meta": {"latency_ms": latency_ms},
    }

def get_identity(apiKey, **_extra):
    import json, os, datetime, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0087000" if __import__("os").path.isdir("./environment_mix/0087000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _utc_day_start(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _log_event(api_key_id, st, msg=None):
        events = _load("download_events.json")
        rid = "req_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "render_job_id": "reqlog",
            "artifact_id": "reqlog",
            "output_path": "/__request_log__/get_identity",
            "status": st,
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "created_at": now_iso,
            "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        events.append(row)
        _save("download_events.json", events)

    if not isinstance(apiKey, str) or not apiKey.strip():
        _log_event(None, "failed", "unauthorized: missing apiKey")
        return _err("UNAUTHORIZED", "Missing API key")

    keys = _load("api_keys.json")
    api_row = None
    for k in keys:
        if k.get("id") == apiKey:
            api_row = k
            break
    if api_row is None:
        h = hashlib.sha256(apiKey.encode("utf-8")).hexdigest()
        for k in keys:
            if k.get("key_hash") == h:
                api_row = k
                break
    if api_row is None:
        _log_event(None, "failed", "unauthorized: invalid apiKey")
        return _err("UNAUTHORIZED", "Invalid API key")
    if api_row.get("status") != "active":
        _log_event(api_row.get("id"), "failed", "unauthorized: api key revoked")
        return _err("UNAUTHORIZED", "API key is revoked")

    api_key_id = api_row.get("id")

    # compute consumption
    events = _load("download_events.json")
    window_start = now - datetime.timedelta(seconds=60)
    used_60s = 0
    for ev in events:
        if ev.get("api_key_id") != api_key_id:
            continue
        st = _parse_dt(ev.get("started_at"))
        if st and st >= window_start:
            used_60s += 1

    jobs = _load("render_jobs.json")
    day_start = _utc_day_start(now)
    renders_today = 0
    for j in jobs:
        if j.get("api_key_id") != api_key_id:
            continue
        if j.get("status") not in ("queued", "rendering", "succeeded", "failed"):
            continue
        ca = _parse_dt(j.get("created_at"))
        if ca and ca >= day_start:
            renders_today += 1

    # update last_used_at
    for k in keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log_event(api_key_id, "succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "api_key": {
            "id": api_row.get("id"),
            "name": api_row.get("name"),
            "status": api_row.get("status"),
            "created_at": api_row.get("created_at"),
            "last_used_at": api_row.get("last_used_at"),
        },
        "scopes": ["charts:read", "charts:write", "renders:read", "renders:write"],
        "rate_limit": {
            "requests_per_minute_limit": api_row.get("requests_per_minute_limit"),
            "used_last_60s": used_60s,
            "remaining_last_60s": max(0, int(api_row.get("requests_per_minute_limit") or 0) - used_60s),
        },
        "quota": {
            "renders_per_day_limit": api_row.get("renders_per_day_limit"),
            "renders_today": renders_today,
            "renders_remaining_today": max(0, int(api_row.get("renders_per_day_limit") or 0) - renders_today),
            "day_start_utc": day_start.isoformat(),
        },
        "meta": {"latency_ms": latency_ms},
    }
